def run_agent(model, tools, goal, max_steps=10):
    context = [{"role": "user", "content": goal}]

    for _ in range(max_steps):
        step = model(context)

        if step["type"] == "final":
            return step["answer"]

        if step["type"] == "tool_call":
            name = step["name"]
            args = step.get("args", {})
            if name not in tools:
                observation = f"error: unknown tool '{name}'"
            else:
                try:
                    result = tools[name](**args)
                    observation = f"result: {result}"
                except Exception as e:
                    observation = f"error: {e}"
            context.append({"role": "tool", "name": name, "content": observation})
            continue

        return f"error: unrecognized step type '{step['type']}'"

    return "error: reached step limit without final answer"

import time
import random
import functools

def retry(max_attempts=3, base_delay=0.5, factor=2.0, jitter=True,
          retry_on=(TimeoutError, ConnectionError)):
    def decorator(fn):
        @functools.wraps(fn)
        def wrapper(*args, **kwargs):
            attempt = 0
            while True:
                try:
                    return fn(*args, **kwargs)
                except retry_on as e:
                    attempt += 1
                    if attempt >= max_attempts:
                        raise
                    delay = base_delay * (factor ** (attempt - 1))
                    if jitter:
                        delay += random.uniform(0, base_delay)
                    time.sleep(delay)
        return wrapper
    return decorator

import re
import json

def parse_react(text):
    # Final answer takes precedence
    final = re.search(r"Final Answer:\s*(.*)", text, re.DOTALL)
    if final:
        return {"type": "final", "answer": final.group(1).strip()}

    thought_m = re.search(r"Thought:\s*(.*?)(?=\n(?:Action|Final Answer):|$)",
                          text, re.DOTALL)
    action_m = re.search(r"Action:\s*(.*?)(?=\n(?:Action Input):|$)",
                         text, re.DOTALL)
    input_m = re.search(r"Action Input:\s*(.*)", text, re.DOTALL)

    if not action_m:
        raise ValueError("no Action or Final Answer found in output")

    raw_input = input_m.group(1).strip() if input_m else ""
    try:
        parsed_input = json.loads(raw_input)
    except json.JSONDecodeError:
        parsed_input = raw_input

    return {
        "type": "tool_call",
        "thought": thought_m.group(1).strip() if thought_m else "",
        "action": action_m.group(1).strip(),
        "action_input": parsed_input,
    }

import json

class LoopDetector:
    def __init__(self, max_repeats=3):
        self.max_repeats = max_repeats
        self.last_key = None
        self.count = 0

    def _key(self, name, args):
        # Stable key independent of dict ordering
        return name + "|" + json.dumps(args, sort_keys=True)

    def check(self, name, args):
        key = self._key(name, args)
        if key == self.last_key:
            self.count += 1
        else:
            self.last_key = key
            self.count = 1
        return self.count >= self.max_repeats

class ToolRegistry:
    def __init__(self):
        self._tools = {}

    def register(self, name, description, required=()):
        def decorator(fn):
            self._tools[name] = {
                "fn": fn,
                "description": description,
                "required": tuple(required),
            }
            return fn
        return decorator

    def schemas(self):
        return [
            {"name": n, "description": t["description"], "required": list(t["required"])}
            for n, t in self._tools.items()
        ]

    def dispatch(self, name, args):
        tool = self._tools.get(name)
        if tool is None:
            return {"ok": False, "error": f"unknown tool '{name}'"}

        missing = [r for r in tool["required"] if r not in args]
        if missing:
            return {"ok": False, "error": f"missing required args: {missing}"}

        try:
            result = tool["fn"](**args)
            return {"ok": True, "result": result}
        except Exception as e:
            return {"ok": False, "error": str(e)}

import asyncio

async def run_one(tools, call):
    name = call["name"]
    args = call.get("args", {})
    fn = tools.get(name)
    if fn is None:
        return {"name": name, "ok": False, "error": f"unknown tool '{name}'"}
    try:
        result = await fn(**args)
        return {"name": name, "ok": True, "result": result}
    except Exception as e:
        return {"name": name, "ok": False, "error": str(e)}

async def run_parallel(tools, calls):
    tasks = [run_one(tools, c) for c in calls]
    # return_exceptions is unnecessary since run_one never raises,
    # but each call is isolated so one failure cannot cancel others.
    return await asyncio.gather(*tasks)
